/* Flags to report status/failure cases for a power generator (used in GENERATOR_STATUS). Note that FAULTS are conditions that cause the generator to fail. Warnings are conditions that require attention before the next use (they indicate the system is not operating properly). */
type MavGeneratorStatusFlag uint32

const (
	/* Generator is off. */
	MAV_GENERATOR_STATUS_FLAG_OFF MavGeneratorStatusFlag = 1

	/* Generator is ready to start generating power. */
	MAV_GENERATOR_STATUS_FLAG_READY MavGeneratorStatusFlag = 2

	/* Generator is generating power. */
	MAV_GENERATOR_STATUS_FLAG_GENERATING MavGeneratorStatusFlag = 4

	/* Generator is charging the batteries (generating enough power to charge and provide the load). */
	MAV_GENERATOR_STATUS_FLAG_CHARGING MavGeneratorStatusFlag = 8

	/* Generator is operating at a reduced maximum power. */
	MAV_GENERATOR_STATUS_FLAG_REDUCED_POWER MavGeneratorStatusFlag = 16

	/* Generator is providing the maximum output. */
	MAV_GENERATOR_STATUS_FLAG_MAXPOWER MavGeneratorStatusFlag = 32

	/* Generator is near the maximum operating temperature, cooling is insufficient. */
	MAV_GENERATOR_STATUS_FLAG_OVERTEMP_WARNING MavGeneratorStatusFlag = 64

	/* Generator hit the maximum operating temperature and shutdown. */
	MAV_GENERATOR_STATUS_FLAG_OVERTEMP_FAULT MavGeneratorStatusFlag = 128

	/* Power electronics are near the maximum operating temperature, cooling is insufficient. */
	MAV_GENERATOR_STATUS_FLAG_ELECTRONICS_OVERTEMP_WARNING MavGeneratorStatusFlag = 256

	/* Power electronics hit the maximum operating temperature and shutdown. */
	MAV_GENERATOR_STATUS_FLAG_ELECTRONICS_OVERTEMP_FAULT MavGeneratorStatusFlag = 512

	/* Power electronics experienced a fault and shutdown. */
	MAV_GENERATOR_STATUS_FLAG_ELECTRONICS_FAULT MavGeneratorStatusFlag = 1024

	/* The power source supplying the generator failed e.g. mechanical generator stopped, tether is no longer providing power, solar cell is in shade, hydrogen reaction no longer happening. */
	MAV_GENERATOR_STATUS_FLAG_POWERSOURCE_FAULT MavGeneratorStatusFlag = 2048

	/* Generator controller having communication problems. */
	MAV_GENERATOR_STATUS_FLAG_COMMUNICATION_WARNING MavGeneratorStatusFlag = 4096

	/* Power electronic or generator cooling system error. */
	MAV_GENERATOR_STATUS_FLAG_COOLING_WARNING MavGeneratorStatusFlag = 8192

	/* Generator controller power rail experienced a fault. */
	MAV_GENERATOR_STATUS_FLAG_POWER_RAIL_FAULT MavGeneratorStatusFlag = 16384

	/* Generator controller exceeded the overcurrent threshold and shutdown to prevent damage. */
	MAV_GENERATOR_STATUS_FLAG_OVERCURRENT_FAULT MavGeneratorStatusFlag = 32768

	/* Generator controller detected a high current going into the batteries and shutdown to prevent battery damage. */
	MAV_GENERATOR_STATUS_FLAG_BATTERY_OVERCHARGE_CURRENT_FAULT MavGeneratorStatusFlag = 65536

	/* Generator controller exceeded it's overvoltage threshold and shutdown to prevent it exceeding the voltage rating. */
	MAV_GENERATOR_STATUS_FLAG_OVERVOLTAGE_FAULT MavGeneratorStatusFlag = 131072

	/* Batteries are under voltage (generator will not start). */
	MAV_GENERATOR_STATUS_FLAG_BATTERY_UNDERVOLT_FAULT MavGeneratorStatusFlag = 262144

	/* Generator start is inhibited by e.g. a safety switch. */
	MAV_GENERATOR_STATUS_FLAG_START_INHIBITED MavGeneratorStatusFlag = 524288

	/* Generator requires maintenance. */
	MAV_GENERATOR_STATUS_FLAG_MAINTENANCE_REQUIRED MavGeneratorStatusFlag = 1048576

	/* Generator is not ready to generate yet. */
	MAV_GENERATOR_STATUS_FLAG_WARMING_UP MavGeneratorStatusFlag = 2097152

	/* Generator is idle. */
	MAV_GENERATOR_STATUS_FLAG_IDLE MavGeneratorStatusFlag = 4194304
)

