/* The heartbeat message shows that a system or component is present and responding. The type and autopilot fields (along with the message component id), allow the receiving system to treat further messages from this system appropriately (e.g. by laying out the user interface based on the autopilot). This microservice is documented at https://mavlink.io/en/services/heartbeat.html */
type Heartbeat struct {
	/* A bitfield for use for autopilot-specific flags */
	CustomMode uint32

	/* Vehicle or component type. For a flight controller component the vehicle type (quadrotor, helicopter, etc.). For other components the component type (e.g. camera, gimbal, etc.). This should be used in preference to component id for identifying the component type. */
	Type MavType `mavlink:"byte"`

	/* Autopilot type / class. Use MAV_AUTOPILOT_INVALID for components that are not flight controllers. */
	Autopilot MavAutopilot `mavlink:"byte"`

	/* System mode bitmap. */
	BaseMode MavModeFlag `mavlink:"byte,bitmask"`

	/* System status flag. */
	SystemStatus MavState `mavlink:"byte"`

	/* MAVLink version, not writable by user, gets added by protocol because of magic data type: uint8_t_mavlink_version */
	MavlinkVersion byte
}

func (m *Heartbeat) ID() int        { return 0 }
func (m *Heartbeat) CRCExtra() byte { return 50 }

func (m *Heartbeat) MarshalV1(buf []byte) []byte {
	buf = marshalUint32(buf, (m.CustomMode))
	buf = marshalByte(buf, byte(m.Type))
	buf = marshalByte(buf, byte(m.Autopilot))
	buf = marshalByte(buf, byte(m.BaseMode))
	buf = marshalByte(buf, byte(m.SystemStatus))
	buf = marshalByte(buf, (m.MavlinkVersion))

	return buf
}

func (m *Heartbeat) MarshalV2(buf []byte) []byte {
	buf = m.MarshalV1(buf)

	return buf
}

func (m *Heartbeat) UnmarshalV1(buf []byte) []byte {

	buf, m.CustomMode = unmarshalUint32(buf)

	{
		var v byte
		buf, v = unmarshalByte(buf)
		m.Type = MavType(v)
	}

	{
		var v byte
		buf, v = unmarshalByte(buf)
		m.Autopilot = MavAutopilot(v)
	}

	{
		var v byte
		buf, v = unmarshalByte(buf)
		m.BaseMode = MavModeFlag(v)
	}

	{
		var v byte
		buf, v = unmarshalByte(buf)
		m.SystemStatus = MavState(v)
	}

	buf, m.MavlinkVersion = unmarshalByte(buf)

	return buf
}

func (m *Heartbeat) UnmarshalV2(buf []byte) []byte {
	buf = m.UnmarshalV1(buf)

	return buf
}

/* Sensor and subsystem status information. Provides a compact representation of sensor/subsystem status and a few other basic statistics. */
type SysStatus struct {
	/* Bitmap showing which onboard controllers and sensors are present. Value of 0: not present. Value of 1: present. */
	OnboardControlSensorsPresent MavSysStatusSensor `mavlink:"uint32,bitmask"`

	/* Bitmap showing which onboard controllers and sensors are enabled:  Value of 0: not enabled. Value of 1: enabled. */
	OnboardControlSensorsEnabled MavSysStatusSensor `mavlink:"uint32,bitmask"`

	/* Bitmap showing which onboard controllers and sensors have an error (or are operational). Value of 0: error. Value of 1: healthy. */
	OnboardControlSensorsHealth MavSysStatusSensor `mavlink:"uint32,bitmask"`

	/* Maximum usage in percent of the mainloop time. Values: [0-1000] - should always be below 1000 */
	Load uint16

	/* Battery voltage, UINT16_MAX: Voltage not sent by autopilot */
	VoltageBattery uint16

	/* Battery current, -1: Current not sent by autopilot */
	CurrentBattery int16

	/* Communication drop rate, (UART, I2C, SPI, CAN), dropped packets on all links (packets that were corrupted on reception on the MAV) */
	DropRateComm uint16

	/* Communication errors (UART, I2C, SPI, CAN), dropped packets on all links (packets that were corrupted on reception on the MAV) */
	ErrorsComm uint16

	/* Autopilot-specific errors */
	ErrorsCount1 uint16

	/* Autopilot-specific errors */
	ErrorsCount2 uint16

	/* Autopilot-specific errors */
	ErrorsCount3 uint16

	/* Autopilot-specific errors */
	ErrorsCount4 uint16

	/* Battery energy remaining, -1: Battery remaining energy not sent by autopilot */
	BatteryRemaining int8

	/* Bitmap showing which onboard controllers and sensors are present. Value of 0: not present. Value of 1: present. */
	OnboardControlSensorsPresentExtended MavSysStatusSensorExtended `mavlink:"uint32,bitmask"` /*EXTENSION*/

	/* Bitmap showing which onboard controllers and sensors are enabled:  Value of 0: not enabled. Value of 1: enabled. */
	OnboardControlSensorsEnabledExtended MavSysStatusSensorExtended `mavlink:"uint32,bitmask"` /*EXTENSION*/

	/* Bitmap showing which onboard controllers and sensors have an error (or are operational). Value of 0: error. Value of 1: healthy. */
	OnboardControlSensorsHealthExtended MavSysStatusSensorExtended `mavlink:"uint32,bitmask"` /*EXTENSION*/

}

